import{_ as t}from"./chunks/image17.hU0mtZ2h.js";import{_ as n,o,c as a,ah as s}from"./chunks/framework.CvRIgsZ1.js";const i="/projects/MentorPi-T1/en/latest/assets/image4.a5w3ZVTV.png",r="/projects/MentorPi-T1/en/latest/assets/image7.CbXEHiL5.png",l="data:image/png;base64,",c="/projects/MentorPi-T1/en/latest/assets/image14.BPa__NNH.png",d="/projects/MentorPi-T1/en/latest/assets/image16.CKiop7Qk.png",p="/projects/MentorPi-T1/en/latest/assets/image18.DuZgXmZ9.png",h="/projects/MentorPi-T1/en/latest/assets/image19.CWyeyLuI.png",w=JSON.parse('{"title":"12. Master Slave And Group Control","description":"","frontmatter":{},"headers":[],"relativePath":"docs/12.master_slave_and_group_control.md","filePath":"docs/12.master_slave_and_group_control.md"}'),g={name:"docs/12.master_slave_and_group_control.md"};function u(m,e,v,b,y,f){return o(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="_12-master-slave-and-group-control" tabindex="-1">12. Master Slave And Group Control <a class="header-anchor" href="#_12-master-slave-and-group-control" aria-label="Permalink to &quot;12. Master Slave And Group Control&quot;">​</a></h1><h2 id="_12-1-master-slave-and-environment-variable-configuration" tabindex="-1">12.1 Master-Slave and Environment Variable Configuration <a class="header-anchor" href="#_12-1-master-slave-and-environment-variable-configuration" aria-label="Permalink to &quot;12.1 Master-Slave and Environment Variable Configuration&quot;">​</a></h2><h3 id="_12-1-1-preparation" tabindex="-1">12.1.1 Preparation <a class="header-anchor" href="#_12-1-1-preparation" aria-label="Permalink to &quot;12.1.1 Preparation&quot;">​</a></h3><p>(1) Prepare at least two devices (this lesson uses two MentorPi units as an example).</p><p>(2) Set up the development environment by referring to <a href="./2.remote_tool_installation_and_container_access.html#vnc-installation-and-connection">&quot;<strong>2. Set Development Enviroment -&gt; 2.1 VNC Installation and Connection</strong>&quot;</a>, and download and install the remote access tool <strong>VNC</strong>.</p><h3 id="_12-1-2-program-logic" tabindex="-1">12.1.2 Program Logic <a class="header-anchor" href="#_12-1-2-program-logic" aria-label="Permalink to &quot;12.1.2 Program Logic&quot;">​</a></h3><p>By connecting the master and slave devices to the same network and assigning different namespaces, the broadcast program can send velocity commands to the slave devices, enabling coordinated multi-device control. In this example, a hotspot created by a Raspberry Pi is used for the network connection.</p><p id="anchor_12_1_3"></p><h3 id="_12-1-3-network-configuration" tabindex="-1">12.1.3 Network Configuration <a class="header-anchor" href="#_12-1-3-network-configuration" aria-label="Permalink to &quot;12.1.3 Network Configuration&quot;">​</a></h3><ul><li><strong>Configure Host Network</strong></li></ul><p>(1) Power on one MentorPi device and designate it as the master. Once it has booted, remotely access its desktop.</p><p>(2) Open a terminal and navigate to the project directory by entering the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><p>(3) Open the Wi-Fi configuration file using the Vim editor:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim wifi_conf.py</span></span></code></pre></div><p>(4) Press the <code>i</code> key to enter <strong>edit mode</strong>. Locate the two lines of code related to the hotspot password (as shown in the reference image), and update the password as needed.</p><img loading="lazy" height="423" width="749" src="'+i+'" class="common_img"><p>(5) After making the changes, press <code>Esc</code> to exit <strong>edit mode</strong>, then type <code>:wq</code> and press <code>Enter</code> to save and exit the file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><p>(6) Reboot the master device by running:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><p>(7) Once the device has restarted, connect to the master&#39;s Wi-Fi using the updated password. The default password is <strong>&quot;hiwonder&quot;</strong> unless you specified a different one during configuration.</p><ul><li><strong>Configure Slave Network</strong></li></ul><p>(1) Power on the slave device and remotely access its desktop environment.</p><p>(2) Open a terminal and navigate to the project directory with the following command:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cd hiwonder-toolbox</span></span></code></pre></div><p>(3) Use the Vim editor to open the Wi-Fi configuration file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo vim wifi_conf.py</span></span></code></pre></div><p>(4) Press <code>i</code> to enter <strong>&quot;edit mode&quot;</strong>. Locate the three lines of code shown in the reference image and modify the Wi-Fi name and password as indicated.</p><p>Located the indicated codes.</p><img loading="lazy" height="424" width="748" src="'+r+'" class="common_img"><p>Set the <strong>network mode to &quot;2&quot;</strong> to enable <strong>&quot;LAN mode&quot;</strong>. Use <strong>&quot;HW-123&quot;</strong> as the Wi-Fi name and <strong>&quot;hiwonder&quot;</strong> as the password—these should match the hotspot settings configured on the master device in <a href="#anchor_12_1_3">12.1.3 Network Configuration</a>.</p><p>(5) Once editing is complete, press <code>Esc</code> to exit <strong>edit mode</strong>, then type <code>:wq</code> and press <code>Enter</code> to save and close the file:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>:wq</span></span></code></pre></div><p>(6) Reboot the device by entering the following command (this step is <strong>required</strong>):</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo reboot</span></span></code></pre></div><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>When MentorPi starts in <strong>&quot;LAN mode&quot;</strong>, it will first attempt to automatically connect to the predefined network. During this process, <code>LED2</code> on the Raspberry Pi expansion board will flash rapidly, indicating that the device is actively searching for the network.</p></li><li><p>If the target network cannot be found after <strong>three consecutive search attempts</strong>, MentorPi will automatically switch to <strong>&quot;Direct Connection mode&quot;</strong> (indicated by <code>LED2</code> flashing slowly).</p></li><li><p>Please note that when MentorPi switches back to <strong>&quot;Direct Connection mode&quot;</strong> due to a failed LAN connection, the settings in the <code>wifi_conf.py</code> file <strong>will not be updated automatically</strong>—they will still reflect the LAN configuration. Therefore, unless the file is manually modified, MentorPi will continue to attempt <strong>&quot;LAN mode&quot;</strong> first on the next startup.</p></li></ul></section><p id="anchor_12_1_4"></p><h3 id="_12-1-4-configure-environment-variable" tabindex="-1">12.1.4 Configure Environment Variable <a class="header-anchor" href="#_12-1-4-configure-environment-variable" aria-label="Permalink to &quot;12.1.4 Configure Environment Variable&quot;">​</a></h3><ul><li><strong>Configuring Environment Variables on the Master Device</strong></li></ul><p>(1) Select one MentorPi vehicle as the master and power it on. Use VNC to remotely connect to the Raspberry Pi desktop.</p><p>(2) Click <img loading="lazy" height="29" width="31" src="'+l+'"> in the top-left corner of the desktop to open the Terminator terminal.</p><p>(3) Ensure the master device is connected to the USB game controller receiver.</p><p>(4) Enter the command to disable automatic startup of the gameplay and press Enter:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>~/.stop_ros.sh</span></span></code></pre></div><p>(5) Open the <code>.typerc</code> file to configure environment variables for the master device by entering:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>vim /home/ubuntu/ros2_ws/.typerc</span></span></code></pre></div><p>(6) Press the <code>i</code> key to enter <strong>edit mode</strong>. Enable the master-slave settings by setting the master to <code>robot_1/</code>.</p><img loading="lazy" height="325" width="812" src="'+c+'" class="common_img"><p>(7) After making the changes, press <code>Esc</code>, then type <code>:wq</code> and press <code>Enter</code> to save and exit.</p><p>(8) Finally, enter the following command to apply the master configuration:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>source ~/.zshrc</span></span></code></pre></div><ul><li><strong>Configuring Environment Variables on the Slave Device</strong></li></ul><p>(1) Connect your mobile app to the Wi-Fi network generated by the master device. Perform a search, and you will see two car icons displayed. Long-press the icon representing the slave device to reveal its <code>IP</code> address. Use this <code>IP</code> to follow the instructions in <a href="./2.remote_tool_installation_and_container_access.html#vnc-installation-and-connection">&quot;<strong>2. Set Development Environment -&gt; 2.1 VNC Installation and Connection</strong>&quot;</a>.</p><img loading="lazy" height="371" width="808" src="'+d+'" class="common_img" style="width:700px;"><img loading="lazy" height="692" width="1266" src="'+t+'" class="common_img" style="width:700px;"><p>(2) After accessing the device, follow the steps in <a href="#anchor_12_1_4">12.1.4 Configure Environment Variable-&gt; Configuring Environment Variables on the Master Device</a> First, open the <code>.typerc</code> file and set the slave device&#39;s environment variable <code>HOST</code> to <code>robot_2</code>. Then save and exit the file. Finally, run the command <code>source ~/.zshrc</code> to refresh the environment variables.</p><img loading="lazy" height="400" width="798" src="'+p+'" class="common_img"><img loading="lazy" height="226" width="807" src="'+h+'" class="common_img"><h2 id="_12-2-group-control" tabindex="-1">12.2 Group Control <a class="header-anchor" href="#_12-2-group-control" aria-label="Permalink to &quot;12.2 Group Control&quot;">​</a></h2><h3 id="_12-2-1-time-synchronization" tabindex="-1">12.2.1 Time Synchronization <a class="header-anchor" href="#_12-2-1-time-synchronization" aria-label="Permalink to &quot;12.2.1 Time Synchronization&quot;">​</a></h3><p>(1) On the master device&#39;s terminal, check the current system time by entering the command below:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>date</span></span></code></pre></div><p>(2) On the slave device, synchronize its system time with the master&#39;s time by entering:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo date -s &quot;2024-10-29 22:46:31&quot;</span></span></code></pre></div><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><ul><li><p>If you experience noticeable desynchronization during joystick control between the master and slave devices, it is likely caused by inconsistent system times. In such cases, please repeat the synchronization process.</p></li><li><p>Updating the slave&#39;s system time based on the master&#39;s reported time takes some time to execute, meaning the master&#39;s actual time will have advanced by the time the update is applied. To minimize this discrepancy, start a stopwatch or manually count seconds after retrieving the master&#39;s time. Then, add this elapsed time to the master&#39;s reported time when setting the slave&#39;s time.</p></li><li><p>After synchronizing, verify by quickly running the <code>date</code> command on both master and slave terminals. If their system times closely match, the synchronization is successful.</p></li></ul></section><h3 id="_12-2-2-program-execution" tabindex="-1">12.2.2 Program Execution <a class="header-anchor" href="#_12-2-2-program-execution" aria-label="Permalink to &quot;12.2.2 Program Execution&quot;">​</a></h3><p><a href="../_static/source_code/multi.zip">Source Code</a></p><p>(1) On the master device, open three terminal windows and run the following programs in each:</p><ul><li><code>multi_controller.launch.py</code>: controls the chassis</li><li><code>joystick_control_multi.py</code>: manages joystick input</li><li><code>joy_node</code>: starts the joystick communication node</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch multi multi_controller.launch.py</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python3 ros2_ws/src/multi/launch/joystick_control_multi.py</span></span></code></pre></div><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 run joy joy_node</span></span></code></pre></div><p>(2) On the slave device, enter the following command to run the program.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ros2 launch multi multi_controller.launch.py</span></span></code></pre></div><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>For every subsequent startup when you want to use multi-device control, you must first disable the auto-start services on both the master and slave devices, and synchronize their system times.</p></section><h3 id="_12-2-3-group-control-operation" tabindex="-1">12.2.3 Group Control Operation <a class="header-anchor" href="#_12-2-3-group-control-operation" aria-label="Permalink to &quot;12.2.3 Group Control Operation&quot;">​</a></h3><p>(1) Turn ON the controller. Both the red and green <code>LEDs</code> on the controller will start blinking simultaneously.</p><p>(2) Wait a few seconds for the robot and controller to pair automatically. Once paired successfully, the green LED will remain solid while the red <code>LED</code> turns off.</p><p>(3) When the controller connects to the master device, pressing the Start button will trigger a beep from the buzzers on both vehicles.</p><section class="doc-level-one-block" data-doc-level-one-id="note" data-doc-level-one-label="{Note}"><p>Gently pushing the joystick in any direction will result in slow-speed movement.</p></section><table tabindex="0"><thead><tr><th style="text-align:center;">Key</th><th style="text-align:center;">Function</th><th style="text-align:center;">Operation</th></tr></thead><tbody><tr><td style="text-align:center;">START</td><td style="text-align:center;">Stop and reset the robot</td><td style="text-align:center;">Press</td></tr><tr><td style="text-align:center;">Left joystick up</td><td style="text-align:center;">Move forward</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left joystick down</td><td style="text-align:center;">Move backward</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left joystick left</td><td style="text-align:center;">Turn left (mecanum wheel chassis only)</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Left joystick right</td><td style="text-align:center;">Turn right (mecanum wheel chassis only)</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Right joystick left</td><td style="text-align:center;">Turn left (Ackermann steering—front wheels only)</td><td style="text-align:center;">Push</td></tr><tr><td style="text-align:center;">Right joystick right</td><td style="text-align:center;">Turn right (Ackermann steering—front wheels only)</td><td style="text-align:center;">Push</td></tr></tbody></table>',82)])])}const x=n(g,[["render",u]]);export{w as __pageData,x as default};
